 27	public final class Main {
 28	    private static final Logger log = LoggerFactory.getLogger(Main.class);
 29	    private static final ObjectMapper JSON = new ObjectMapper()
 30	            .enable(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN)
 31	            .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
 32	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
 33	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
 34	    private static final Pattern DAY = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
 35	
 36	    public static void main(String[] args) {
 37	        Config config = Config.fromEnv(System.getenv());
 38	        if (config.dbUrl() == null) {
 39	            throw new IllegalStateException("DB_URL não informado");
 40	        }
 41	        Database db = new Database(config.dbUrl(), config.dbUser(), config.dbPassword());
 42	        db.migrate();
 43	        Service service = new Service(db, Clock.systemUTC(), config);
 44	        Javalin app = create(service);
 45	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 46	            app.stop();
 47	            db.close();
 48	        }));
 49	        app.start("0.0.0.0", config.port());
 50	        log.info("Pousada Maré Alta no ar na porta {} (modo de teste: {})", config.port(), config.testMode());
 51	    }
 52	
 53	    public static Javalin create(Service service) {
 54	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 55	
 56	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 57	        app.exception(Exception.class, (e, ctx) -> {
 58	            log.error("Erro inesperado", e);
 59	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 60	        });
 61	        app.error(404, ctx -> {
 62	            if (ctx.result() == null || ctx.result().isEmpty() || "Not found".equalsIgnoreCase(ctx.result())) {
 63	                error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
 64	            }
 65	        });
 66	
 67	        app.get("/rooms", ctx -> {
 68	            List<Map<String, Object>> out = new ArrayList<>();
 69	            for (Room r : service.rooms()) {
 70	                Map<String, Object> m = new LinkedHashMap<>();
 71	                m.put("number", r.number());
 72	                m.put("type", r.type());
 73	                m.put("capacity", r.capacity());
 74	                m.put("nightlyRate", r.nightlyRate());
 75	                out.add(m);
 76	            }
 77	            json(ctx, 200, out);
 78	        });
 79	
 80	        app.post("/reservations", ctx -> json(ctx, 201, view(service.create(parseNew(ctx.body())))));
 81	        app.get("/reservations/{id}", ctx -> json(ctx, 200, view(service.get(id(ctx)))));
 82	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, view(service.confirm(id(ctx)))));
 83	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, view(service.cancel(id(ctx)))));
 84	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, view(service.checkIn(id(ctx)))));
 85	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, view(service.checkOut(id(ctx)))));
 86	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, view(service.document(id(ctx)))));
 87	
 88	        app.get("/messages", ctx -> {
 89	            List<Map<String, Object>> out = new ArrayList<>();
 90	            for (Service.StoredMessage m : service.messages()) {
 91	                Map<String, Object> v = new LinkedHashMap<>();
 92	                v.put("id", m.id());
 93	                v.put("channel", m.channel());
 94	                v.put("to", m.to());
 95	                v.put("subject", m.subject());
 96	                v.put("body", m.body());
 97	                v.put("status", m.status());
 98	                out.add(v);
 99	            }
100	            json(ctx, 200, out);
101	        });
102	
103	        app.get("/reports/occupancy", ctx -> {
104	            String d = ctx.queryParam("date");
105	            if (d == null || !DAY.matcher(d).matches()) throw ApiException.invalid("Informe date no formato AAAA-MM-DD");
106	            csv(ctx, service.occupancyCsv(date(d, "date")));
107	        });
108	        app.get("/reports/revenue", ctx -> {
109	            String m = ctx.queryParam("month");
110	            if (m == null || !MONTH.matcher(m).matches()) throw ApiException.invalid("Informe month no formato AAAA-MM");
111	            try {
112	                csv(ctx, service.revenueCsv(YearMonth.parse(m)));
113	            } catch (DateTimeException e) {
114	                throw ApiException.invalid("month inválido");
115	            }
116	        });
117	        return app;
118	    }
119	
120	    // ---------- entrada e saída ----------
121	
122	    private static long id(Context ctx) {
123	        try {
124	            return Long.parseLong(ctx.pathParam("id"));
125	        } catch (NumberFormatException e) {
126	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não existe");
127	        }
128	    }
129	
130	    private static void json(Context ctx, int status, Object body) {
131	        try {
132	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
133	        } catch (JsonProcessingException e) {
134	            throw new IllegalStateException(e);
135	        }
136	    }
137	
138	    private static void csv(Context ctx, String body) {
139	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
140	    }
141	
142	    private static void error(Context ctx, int status, String code, String message) {
143	        Map<String, Object> m = new LinkedHashMap<>();
144	        m.put("error", code);
145	        m.put("message", message);
146	        json(ctx, status, m);
147	    }
148	
149	    private static LocalDate date(String s, String field) {
150	        if (s == null || !DAY.matcher(s).matches()) throw ApiException.invalid(field + " deve estar no formato AAAA-MM-DD");
151	        try {
152	            return LocalDate.parse(s);
153	        } catch (DateTimeException e) {
154	            throw ApiException.invalid(field + " é uma data inválida");
155	        }
156	    }
157	
158	    private static String text(JsonNode root, String field) {
159	        JsonNode n = root.get(field);
160	        if (n == null || !n.isTextual() || n.asText().isBlank()) {
161	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
162	        }
163	        return n.asText();
164	    }
165	
166	    private static Service.NewReservation parseNew(String body) {
167	        JsonNode root;
168	        try {
169	            root = JSON.readTree(body);
170	        } catch (JsonProcessingException e) {
171	            throw ApiException.invalid("Corpo não é um JSON válido");
172	        }
173	        if (root == null || !root.isObject()) throw ApiException.invalid("Corpo deve ser um objeto JSON");
174	
175	        JsonNode roomN = root.get("roomNumber");
176	        JsonNode guestsN = root.get("guests");
177	        if (roomN == null || !roomN.isIntegralNumber() || !roomN.canConvertToInt()) {
178	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: roomNumber");
179	        }
180	        if (guestsN == null || !guestsN.isIntegralNumber() || !guestsN.canConvertToInt()) {
181	            throw ApiException.invalid("Campo obrigatório ausente ou inválido: guests");
182	        }
183	        RatePlan plan;
184	        try {
185	            plan = RatePlan.valueOf(text(root, "ratePlan"));
186	        } catch (IllegalArgumentException e) {
187	            throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
188	        }
189	        String name = text(root, "guestName");
190	        String email = text(root, "guestEmail");
191	        String cpf = text(root, "guestCpf");
192	        LocalDate in = date(text(root, "checkIn"), "checkIn");
193	        LocalDate out = date(text(root, "checkOut"), "checkOut");
194	        if (!out.isAfter(in)) throw ApiException.invalid("checkOut deve ser depois de checkIn");
195	        if (guestsN.asInt() < 1) throw ApiException.invalid("guests deve ser pelo menos 1");
196	        return new Service.NewReservation(roomN.asInt(), name, email, cpf, in, out, guestsN.asInt(), plan);
197	    }
198	
199	    private static Map<String, Object> view(Reservation r) {
200	        Map<String, Object> m = new LinkedHashMap<>();
201	        m.put("id", r.id());
202	        m.put("roomNumber", r.roomNumber());
203	        m.put("guestName", r.guestName());
204	        m.put("guestEmail", r.guestEmail());
205	        m.put("guestCpf", r.guestCpf());
206	        m.put("checkIn", r.checkIn().toString());
207	        m.put("checkOut", r.checkOut().toString());
208	        m.put("guests", r.guests());
209	        m.put("ratePlan", r.ratePlan());
210	        m.put("nights", r.nights());
211	        m.put("subtotal", r.subtotal());
212	        m.put("discount", r.discount());
213	        m.put("total", r.total());
214	        m.put("status", r.status());
215	        m.put("amountPaid", r.amountPaid());
216	        m.put("refund", r.refund());
217	        return m;
218	    }
219	
220	    private static Map<String, Object> view(Receipt d) {
221	        Map<String, Object> m = new LinkedHashMap<>();
222	        m.put("title", Receipt.TITLE);
223	        m.put("reservationId", d.reservationId());
224	        m.put("guestName", d.guestName());
225	        m.put("guestCpf", d.guestCpf());
226	        m.put("roomNumber", d.roomNumber());
227	        m.put("roomType", d.roomType());
228	        m.put("checkIn", d.checkIn().toString());
229	        m.put("checkOut", d.checkOut().toString());
230	        m.put("nights", d.nights());
231	        m.put("subtotal", d.subtotal());
232	        m.put("discount", d.discount());
233	        m.put("total", d.total());
234	        return m;
235	    }
236	}
