244	/** Configuração da instalação, lida das variáveis de ambiente. */
245	public record Config(
246	        int port, String dbUrl, String dbUser, String dbPassword,
247	        boolean testMode, ZoneId zone, Notifications notifications) {
248	
249	    /** Em que modo uma regra de mensagem vale. */
250	    public enum Scope {
251	        ALWAYS, TEST_ONLY, LIVE_ONLY, NEVER;
252	
253	        public boolean appliesTo(boolean testMode) {
254	            return switch (this) {
255	                case ALWAYS -> true;
256	                case TEST_ONLY -> testMode;
257	                case LIVE_ONLY -> !testMode;
258	                case NEVER -> false;
259	            };
260	        }
261	    }
262	
263	    /** Regras das mensagens enviadas; cada instalação escolhe a sua combinação. */
264	    public record Notifications(
265	            Scope addressValidation, Scope archiveCopy, Scope quietHours, Scope dailyLimit,
266	            String archiveAddress, String testAddress,
267	            LocalTime quietStart, LocalTime quietEnd, int maxPerGuestPerDay) {
268	
269	        public static Notifications defaults() {
270	            return new Notifications(Scope.ALWAYS, Scope.LIVE_ONLY, Scope.NEVER, Scope.NEVER,
271	                    "arquivo@pousadamarealta.com.br", "testes@pousadamarealta.com.br",
272	                    LocalTime.of(22, 0), LocalTime.of(7, 0), 5);
273	        }
274	    }
275	
276	    public static Config fromEnv(Map<String, String> env) {
277	        Notifications d = Notifications.defaults();
278	        Notifications n = new Notifications(
279	                scope(env, "HOTEL_RULE_ADDRESS_VALIDATION", d.addressValidation()),
280	                scope(env, "HOTEL_RULE_ARCHIVE_COPY", d.archiveCopy()),
281	                scope(env, "HOTEL_RULE_QUIET_HOURS", d.quietHours()),
282	                scope(env, "HOTEL_RULE_DAILY_LIMIT", d.dailyLimit()),
283	                text(env, "HOTEL_ARCHIVE_ADDRESS", d.archiveAddress()),
284	                text(env, "HOTEL_TEST_ADDRESS", d.testAddress()),
285	                time(env, "HOTEL_QUIET_HOURS_START", d.quietStart()),
286	                time(env, "HOTEL_QUIET_HOURS_END", d.quietEnd()),
287	                Integer.parseInt(text(env, "HOTEL_DAILY_LIMIT", String.valueOf(d.maxPerGuestPerDay()))));
288	        return new Config(
289	                Integer.parseInt(text(env, "PORT", "7070")),
290	                env.get("DB_URL"), env.get("DB_USER"), env.get("DB_PASSWORD"),
291	                "true".equalsIgnoreCase(text(env, "HOTEL_TEST_MODE", "false")),
292	                ZoneId.of(text(env, "HOTEL_ZONE", "America/Sao_Paulo")),
293	                n);
294	    }
295	
296	    private static String text(Map<String, String> env, String key, String def) {
297	        String v = env.get(key);
298	        return v == null || v.isBlank() ? def : v.trim();
299	    }
300	
301	    private static Scope scope(Map<String, String> env, String key, Scope def) {
302	        return Scope.valueOf(text(env, key, def.name()).toUpperCase(Locale.ROOT));
303	    }
304	
305	    private static LocalTime time(Map<String, String> env, String key, LocalTime def) {
306	        return LocalTime.parse(text(env, key, def.toString()));
307	    }
308	}
