 25	/** Regras de negócio e acesso ao banco. */
 26	public final class Service {
 27	    private final Database db;
 28	    private final Clock clock;
 29	    private final Config config;
 30	    private final Messaging.Pipeline pipeline;
 31	
 32	    public record NewReservation(
 33	            int roomNumber, String guestName, String guestEmail, String guestCpf,
 34	            LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
 35	
 36	    public record StoredMessage(
 37	            long id, String channel, String to, String subject, String body, String status) {}
 38	
 39	    public Service(Database db, Clock clock, Config config) {
 40	        this.db = db;
 41	        this.clock = clock;
 42	        this.config = config;
 43	        this.pipeline = new Messaging.Pipeline(config.notifications(), config.testMode());
 44	    }
 45	
 46	    private <T> T run(Database.Work<T> work) {
 47	        try {
 48	            return db.tx(work);
 49	        } catch (SQLException e) {
 50	            throw new IllegalStateException(e);
 51	        }
 52	    }
 53	
 54	    // ---------- quartos ----------
 55	
 56	    public List<Room> rooms() {
 57	        return run(c -> {
 58	            List<Room> out = new ArrayList<>();
 59	            try (Statement s = c.createStatement();
 60	                 ResultSet rs = s.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
 61	                while (rs.next()) out.add(room(rs));
 62	            }
 63	            return out;
 64	        });
 65	    }
 66	
 67	    private static Room room(ResultSet rs) throws SQLException {
 68	        return new Room(rs.getInt("number"), RoomType.valueOf(rs.getString("type")),
 69	                rs.getInt("capacity"), rs.getBigDecimal("nightly_rate"));
 70	    }
 71	
 72	    private static Room findRoom(Connection c, int number, boolean lock) throws SQLException {
 73	        try (PreparedStatement ps = c.prepareStatement(
 74	                "SELECT number, type, capacity, nightly_rate FROM rooms WHERE number = ?" + (lock ? " FOR UPDATE" : ""))) {
 75	            ps.setInt(1, number);
 76	            try (ResultSet rs = ps.executeQuery()) {
 77	                if (!rs.next()) {
 78	                    throw new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + number + " não existe");
 79	                }
 80	                return room(rs);
 81	            }
 82	        }
 83	    }
 84	
 85	    // ---------- reservas ----------
 86	
 87	    public Reservation create(NewReservation n) {
 88	        return run(c -> {
 89	            // o bloqueio da linha do quarto serializa reservas concorrentes do mesmo quarto
 90	            Room room = findRoom(c, n.roomNumber(), true);
 91	            if (n.guests() > room.capacity()) {
 92	                throw new ApiException(422, "CAPACITY_EXCEEDED",
 93	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " pessoas");
 94	            }
 95	            try (PreparedStatement ps = c.prepareStatement("""
 96	                    SELECT 1 FROM reservations
 97	                    WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ? LIMIT 1""")) {
 98	                ps.setInt(1, room.number());
 99	                ps.setDate(2, Date.valueOf(n.checkOut()));
100	                ps.setDate(3, Date.valueOf(n.checkIn()));
101	                try (ResultSet rs = ps.executeQuery()) {
102	                    if (rs.next()) {
103	                        throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites pedidas");
104	                    }
105	                }
106	            }
107	            Pricing.Quote q = Pricing.quote(room, n.checkIn(), n.checkOut(), n.ratePlan());
108	            try (PreparedStatement ps = c.prepareStatement("""
109	                    INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
110	                      guests, rate_plan, nights, subtotal, discount, total, status, amount_paid)
111	                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,'PENDING',0) RETURNING id""")) {
112	                ps.setInt(1, room.number());
113	                ps.setString(2, n.guestName());
114	                ps.setString(3, n.guestEmail());
115	                ps.setString(4, n.guestCpf());
116	                ps.setDate(5, Date.valueOf(n.checkIn()));
117	                ps.setDate(6, Date.valueOf(n.checkOut()));
118	                ps.setInt(7, n.guests());
119	                ps.setString(8, n.ratePlan().name());
120	                ps.setInt(9, q.nights());
121	                ps.setBigDecimal(10, q.subtotal());
122	                ps.setBigDecimal(11, q.discount());
123	                ps.setBigDecimal(12, q.total());
124	                try (ResultSet rs = ps.executeQuery()) {
125	                    rs.next();
126	                    return load(c, rs.getLong(1), false);
127	                }
128	            }
129	        });
130	    }
131	
132	    public Reservation get(long id) {
133	        return run(c -> load(c, id, false));
134	    }
135	
136	    private static Reservation load(Connection c, long id, boolean lock) throws SQLException {
137	        try (PreparedStatement ps = c.prepareStatement("SELECT * FROM reservations WHERE id = ?" + (lock ? " FOR UPDATE" : ""))) {
138	            ps.setLong(1, id);
139	            try (ResultSet rs = ps.executeQuery()) {
140	                if (!rs.next()) {
141	                    throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
142	                }
143	                return reservation(rs);
144	            }
145	        }
146	    }
147	
148	    private static Reservation reservation(ResultSet rs) throws SQLException {
149	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), rs.getString("guest_name"),
150	                rs.getString("guest_email"), rs.getString("guest_cpf"),
151	                rs.getDate("check_in").toLocalDate(), rs.getDate("check_out").toLocalDate(),
152	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), rs.getInt("nights"),
153	                rs.getBigDecimal("subtotal"), rs.getBigDecimal("discount"), rs.getBigDecimal("total"),
154	                Status.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
155	    }
156	
157	    private static Reservation transition(Connection c, long id, Status from, Status to, String verb) throws SQLException {
158	        Reservation r = load(c, id, true);
159	        if (r.status() != from) {
160	            throw ApiException.notAllowed("Não é possível " + verb + " uma reserva com situação " + r.status());
161	        }
162	        try (PreparedStatement ps = c.prepareStatement("UPDATE reservations SET status = ? WHERE id = ?")) {
163	            ps.setString(1, to.name());
164	            ps.setLong(2, id);
165	            ps.executeUpdate();
166	        }
167	        return load(c, id, false);
168	    }
169	
170	    public Reservation confirm(long id) {
171	        return run(c -> {
172	            Reservation r = load(c, id, true);
173	            if (r.status() != Status.PENDING) {
174	                throw ApiException.notAllowed("Não é possível confirmar uma reserva com situação " + r.status());
175	            }
176	            try (PreparedStatement ps = c.prepareStatement(
177	                    "UPDATE reservations SET status = 'CONFIRMED', amount_paid = total WHERE id = ?")) {
178	                ps.setLong(1, id);
179	                ps.executeUpdate();
180	            }
181	            Reservation confirmed = load(c, id, false);
182	            String receipt = receipt(c, confirmed).render();
183	            String body = "Olá, " + confirmed.guestName() + "!\n\n"
184	                    + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
185	                    + receipt + "\n\n"
186	                    + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
187	                    + "Até breve!";
188	            send(c, new Draft(confirmed.guestEmail(), "Reserva confirmada - Pousada Maré Alta", body));
189	            return confirmed;
190	        });
191	    }
192	
193	    public Reservation cancel(long id) {
194	        return run(c -> {
195	            Reservation r = load(c, id, true);
196	            if (r.status() != Status.PENDING && r.status() != Status.CONFIRMED) {
197	                throw ApiException.notAllowed("Não é possível cancelar uma reserva com situação " + r.status());
198	            }
199	            // plano normal devolve o que foi pago (nada, se estava pendente); não reembolsável não devolve
200	            BigDecimal refund = r.ratePlan() == RatePlan.STANDARD ? r.amountPaid() : BigDecimal.ZERO.setScale(2);
201	            try (PreparedStatement ps = c.prepareStatement(
202	                    "UPDATE reservations SET status = 'CANCELLED', refund = ? WHERE id = ?")) {
203	                ps.setBigDecimal(1, refund);
204	                ps.setLong(2, id);
205	                ps.executeUpdate();
206	            }
207	            return load(c, id, false);
208	        });
209	    }
210	
211	    public Reservation checkIn(long id) {
212	        return run(c -> transition(c, id, Status.CONFIRMED, Status.CHECKED_IN, "fazer check-in de"));
213	    }
214	
215	    public Receipt checkOut(long id) {
216	        return run(c -> receipt(c, transition(c, id, Status.CHECKED_IN, Status.CHECKED_OUT, "fazer check-out de")));
217	    }
218	
219	    public Receipt document(long id) {
220	        return run(c -> {
221	            Reservation r = load(c, id, false);
222	            if (!r.status().isPaid()) {
223	                throw ApiException.notAllowed("Só existe comprovante para reserva paga; situação atual: " + r.status());
224	            }
225	            return receipt(c, r);
226	        });
227	    }
228	
229	    private static Receipt receipt(Connection c, Reservation r) throws SQLException {
230	        return Receipt.of(r, findRoom(c, r.roomNumber(), false).type());
231	    }
232	
233	    // ---------- mensagens ----------
234	
235	    private void send(Connection c, Draft draft) throws SQLException {
236	        ZonedDateTime now = ZonedDateTime.now(clock.withZone(config.zone()));
237	        // serializa os envios para o mesmo hóspede, para o limite diário valer sob concorrência
238	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(hashtext(?))")) {
239	            ps.setString(1, Messaging.key(draft.to()));
240	            ps.execute();
241	        }
242	        Messaging.Context ctx = new Messaging.Context(config.testMode(), now, addr -> {
243	            try {
244	                return countSentToday(c, addr, now);
245	            } catch (SQLException e) {
246	                throw new IllegalStateException(e);
247	            }
248	        });
249	        for (Outgoing m : pipeline.process(draft, ctx)) {
250	            try (PreparedStatement ps = c.prepareStatement("""
251	                    INSERT INTO messages (channel, recipient, subject, body, status, guest_address, copy, created_at)
252	                    VALUES (?,?,?,?,?,?,?,?)""")) {
253	                ps.setString(1, m.channel().name());
254	                ps.setString(2, m.to());
255	                ps.setString(3, m.subject());
256	                ps.setString(4, m.body());
257	                ps.setString(5, m.status().name());
258	                ps.setString(6, m.guestAddress());
259	                ps.setBoolean(7, m.copy());
260	                ps.setTimestamp(8, Timestamp.from(now.toInstant()));
261	                ps.executeUpdate();
262	            }
263	        }
264	    }
265	
266	    private static int countSentToday(Connection c, String address, ZonedDateTime now) throws SQLException {
267	        ZonedDateTime start = now.toLocalDate().atStartOfDay(now.getZone());
268	        try (PreparedStatement ps = c.prepareStatement("""
269	                SELECT count(*) FROM messages
270	                WHERE status = 'SENT' AND NOT copy AND lower(guest_address) = lower(?)
271	                  AND created_at >= ? AND created_at < ?""")) {
272	            ps.setString(1, address);
273	            ps.setTimestamp(2, Timestamp.from(start.toInstant()));
274	            ps.setTimestamp(3, Timestamp.from(start.plusDays(1).toInstant()));
275	            try (ResultSet rs = ps.executeQuery()) {
276	                rs.next();
277	                return rs.getInt(1);
278	            }
279	        }
280	    }
281	
282	    public List<StoredMessage> messages() {
283	        return run(c -> {
284	            List<StoredMessage> out = new ArrayList<>();
285	            try (Statement s = c.createStatement();
286	                 ResultSet rs = s.executeQuery("SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id")) {
287	                while (rs.next()) {
288	                    out.add(new StoredMessage(rs.getLong(1), rs.getString(2), rs.getString(3),
289	                            rs.getString(4), rs.getString(5), rs.getString(6)));
290	                }
291	            }
292	            return out;
293	        });
294	    }
