296	    // ---------- relatórios ----------
297	
298	    public String occupancyCsv(LocalDate night) {
299	        return run(c -> {
300	            StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
301	            int occupied = 0;
302	            try (PreparedStatement ps = c.prepareStatement("""
303	                    SELECT r.room_number, m.type, r.id, r.check_in, r.check_out
304	                    FROM reservations r JOIN rooms m ON m.number = r.room_number
305	                    WHERE r.status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND r.check_in <= ? AND r.check_out > ?
306	                    ORDER BY r.room_number, r.id""")) {
307	                ps.setDate(1, Date.valueOf(night));
308	                ps.setDate(2, Date.valueOf(night));
309	                try (ResultSet rs = ps.executeQuery()) {
310	                    while (rs.next()) {
311	                        occupied++;
312	                        sb.append(rs.getInt(1)).append(',').append(rs.getString(2)).append(',')
313	                                .append(rs.getLong(3)).append(',').append(rs.getDate(4).toLocalDate()).append(',')
314	                                .append(rs.getDate(5).toLocalDate()).append('\n');
315	                    }
316	                }
317	            }
318	            int total;
319	            try (Statement s = c.createStatement(); ResultSet rs = s.executeQuery("SELECT count(*) FROM rooms")) {
320	                rs.next();
321	                total = rs.getInt(1);
322	            }
323	            return sb.append("total,").append(occupied).append('/').append(total).append('\n').toString();
324	        });
325	    }
326	
327	    public String revenueCsv(YearMonth month) {
328	        return run(c -> {
329	            StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
330	            BigDecimal sum = BigDecimal.ZERO.setScale(2);
331	            try (PreparedStatement ps = c.prepareStatement("""
332	                    SELECT id, room_number, check_in, check_out, status, amount_paid - COALESCE(refund, 0) AS amount
333	                    FROM reservations
334	                    WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0
335	                    ORDER BY check_in, id""")) {
336	                ps.setDate(1, Date.valueOf(month.atDay(1)));
337	                ps.setDate(2, Date.valueOf(month.plusMonths(1).atDay(1)));
338	                try (ResultSet rs = ps.executeQuery()) {
339	                    while (rs.next()) {
340	                        BigDecimal amount = rs.getBigDecimal("amount").setScale(2);
