 25	/** Regras de negócio e acesso ao banco. */
 26	public final class Service {
 27	    private final Database db;
 28	    private final Clock clock;
 29	    private final Config config;
 30	    private final Messaging.Pipeline pipeline;
 31	
 32	    public record NewReservation(
 33	            int roomNumber, String guestName, String guestEmail, String guestCpf,
 34	            LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
 35	
 36	    public record StoredMessage(
