 54	    // ---------- quartos ----------
 55	
 56	    public List<Room> rooms() {
 57	        return run(c -> {
 58	            List<Room> out = new ArrayList<>();
 59	            try (Statement s = c.createStatement();
 60	                 ResultSet rs = s.executeQuery("SELECT number, type, capacity, nightly_rate FROM rooms ORDER BY number")) {
 61	                while (rs.next()) out.add(room(rs));
 62	            }
 63	            return out;
 64	        });
 65	    }
