211	    public Reservation checkIn(long id) {
212	        return run(c -> transition(c, id, Status.CONFIRMED, Status.CHECKED_IN, "fazer check-in de"));
213	    }
214	
215	    public Receipt checkOut(long id) {
216	        return run(c -> receipt(c, transition(c, id, Status.CHECKED_IN, Status.CHECKED_OUT, "fazer check-out de")));
217	    }
