219	    public Receipt document(long id) {
220	        return run(c -> {
221	            Reservation r = load(c, id, false);
222	            if (!r.status().isPaid()) {
223	                throw ApiException.notAllowed("Só existe comprovante para reserva paga; situação atual: " + r.status());
224	            }
225	            return receipt(c, r);
226	        });
227	    }
