235	    private void send(Connection c, Draft draft) throws SQLException {
236	        ZonedDateTime now = ZonedDateTime.now(clock.withZone(config.zone()));
237	        // serializa os envios para o mesmo hóspede, para o limite diário valer sob concorrência
238	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(hashtext(?))")) {
239	            ps.setString(1, Messaging.key(draft.to()));
240	            ps.execute();
241	        }
242	        Messaging.Context ctx = new Messaging.Context(config.testMode(), now, addr -> {
243	            try {
244	                return countSentToday(c, addr, now);
245	            } catch (SQLException e) {
246	                throw new IllegalStateException(e);
247	            }
248	        });
249	        for (Outgoing m : pipeline.process(draft, ctx)) {
250	            try (PreparedStatement ps = c.prepareStatement("""
251	                    INSERT INTO messages (channel, recipient, subject, body, status, guest_address, copy, created_at)
252	                    VALUES (?,?,?,?,?,?,?,?)""")) {
253	                ps.setString(1, m.channel().name());
254	                ps.setString(2, m.to());
255	                ps.setString(3, m.subject());
256	                ps.setString(4, m.body());
257	                ps.setString(5, m.status().name());
258	                ps.setString(6, m.guestAddress());
259	                ps.setBoolean(7, m.copy());
260	                ps.setTimestamp(8, Timestamp.from(now.toInstant()));
261	                ps.executeUpdate();
262	            }
263	        }
264	    }
