266	    private static int countSentToday(Connection c, String address, ZonedDateTime now) throws SQLException {
267	        ZonedDateTime start = now.toLocalDate().atStartOfDay(now.getZone());
268	        try (PreparedStatement ps = c.prepareStatement("""
269	                SELECT count(*) FROM messages
270	                WHERE status = 'SENT' AND NOT copy AND lower(guest_address) = lower(?)
271	                  AND created_at >= ? AND created_at < ?""")) {
272	            ps.setString(1, address);
273	            ps.setTimestamp(2, Timestamp.from(start.toInstant()));
274	            ps.setTimestamp(3, Timestamp.from(start.plusDays(1).toInstant()));
275	            try (ResultSet rs = ps.executeQuery()) {
276	                rs.next();
277	                return rs.getInt(1);
278	            }
279	        }
280	    }
