  1	package br.com.marealta;
  2	
  3	import br.com.marealta.Config.Notifications;
  4	import java.time.LocalTime;
  5	import java.time.ZonedDateTime;
  6	import java.util.ArrayList;
  7	import java.util.List;
  8	import java.util.Locale;
  9	import java.util.function.ToIntFunction;
 10	
 11	/**
 12	 * Regras das mensagens enviadas. Uma mensagem entra como rascunho, passa por uma cadeia de regras
 13	 * e sai como uma ou mais mensagens (a original, uma possível cópia para o arquivo), enviadas ou bloqueadas.
 14	 *
 15	 * O redirecionamento do modo de teste é sempre a última etapa e age sobre todas as mensagens
 16	 * que vão sair, para que nada chegue a um endereço real nesse modo.
 17	 */
 18	public final class Messaging {
 19	    private Messaging() {}
 20	
 21	    public enum Channel { EMAIL }
 22	
 23	    public enum MessageStatus { SENT, BLOCKED }
 24	
 25	    public record Draft(String to, String subject, String body) {}
 26	
 27	    /**
 28	     * @param guestAddress endereço original do hóspede (para contar o limite diário)
 29	     * @param copy true se for a cópia para o arquivo
 30	     */
 31	    public record Outgoing(
 32	            Channel channel, String to, String subject, String body, MessageStatus status,
 33	            String guestAddress, boolean copy) {
 34	
 35	        boolean sent() {
 36	            return status == MessageStatus.SENT;
 37	        }
 38	    }
 39	
 40	    /** O que as regras precisam saber do momento do envio. */
 41	    public record Context(boolean testMode, ZonedDateTime now, ToIntFunction<String> sentTodayTo) {}
 42	
 43	    public interface Rule {
 44	        void apply(List<Outgoing> messages, Context ctx);
 45	    }
 46	
 47	    public static boolean isValidAddress(String a) {
 48	        if (a == null || a.isEmpty() || a.chars().anyMatch(Character::isWhitespace)) {
 49	            return false;
 50	        }
 51	        int at = a.indexOf('@');
 52	        if (at <= 0 || at != a.lastIndexOf('@')) {
 53	            return false;
 54	        }
 55	        String[] labels = a.substring(at + 1).split("\\.", -1);
 56	        if (labels.length < 2) {
 57	            return false;
 58	        }
 59	        for (String l : labels) {
 60	            if (l.isEmpty()) {
 61	                return false;
 62	            }
 63	        }
 64	        return true;
 65	    }
 66	
 67	    public static final class Pipeline {
 68	        private final List<Rule> rules = new ArrayList<>();
 69	
 70	        public Pipeline(Notifications n, boolean testMode) {
 71	            if (n.addressValidation().appliesTo(testMode)) {
 72	                rules.add(blockWhen((m, c) -> !isValidAddress(m.to())));
 73	            }
 74	            if (n.quietHours().appliesTo(testMode)) {
 75	                rules.add(blockWhen((m, c) -> inQuietHours(c.now().toLocalTime(), n.quietStart(), n.quietEnd())));
 76	            }
 77	            if (n.dailyLimit().appliesTo(testMode)) {
 78	                rules.add(blockWhen((m, c) -> c.sentTodayTo().applyAsInt(m.guestAddress()) >= n.maxPerGuestPerDay()));
 79	            }
 80	            if (n.archiveCopy().appliesTo(testMode)) {
 81	                rules.add(archiveCopy(n.archiveAddress()));
 82	            }
 83	            if (testMode) {
 84	                rules.add(testRedirect(n.testAddress()));
 85	            }
 86	        }
 87	
 88	        public List<Outgoing> process(Draft draft, Context ctx) {
 89	            List<Outgoing> out = new ArrayList<>();
 90	            out.add(new Outgoing(Channel.EMAIL, draft.to(), draft.subject(), draft.body(),
 91	                    MessageStatus.SENT, draft.to(), false));
 92	            for (Rule r : rules) {
 93	                r.apply(out, ctx);
 94	            }
 95	            return out;
 96	        }
 97	    }
 98	
 99	    interface Condition {
100	        boolean test(Outgoing m, Context c);
101	    }
102	
103	    static boolean inQuietHours(LocalTime t, LocalTime start, LocalTime end) {
104	        if (start.equals(end)) {
105	            return false;
106	        }
107	        return start.isBefore(end)
108	                ? !t.isBefore(start) && t.isBefore(end)
109	                : !t.isBefore(start) || t.isBefore(end);
110	    }
111	
112	    /** Bloqueia a mensagem original; o endereço fica como estava. */
113	    private static Rule blockWhen(Condition cond) {
114	        return (messages, ctx) -> {
115	            for (int i = 0; i < messages.size(); i++) {
116	                Outgoing m = messages.get(i);
117	                if (m.sent() && !m.copy() && cond.test(m, ctx)) {
118	                    messages.set(i, new Outgoing(m.channel(), m.to(), m.subject(), m.body(),
119	                            MessageStatus.BLOCKED, m.guestAddress(), false));
120	                }
121	            }
122	        };
123	    }
124	
125	    private static Rule archiveCopy(String archive) {
126	        return (messages, ctx) -> {
127	            for (int i = 0; i < messages.size(); i++) {
128	                Outgoing m = messages.get(i);
129	                if (m.sent() && !m.copy()) {
130	                    messages.add(i + 1, new Outgoing(m.channel(), archive, "[Cópia] " + m.subject(),
131	                            m.body(), MessageStatus.SENT, m.guestAddress(), true));
132	                    i++;
133	                }
134	            }
135	        };
136	    }
137	
138	    private static Rule testRedirect(String testAddress) {
139	        return (messages, ctx) -> {
140	            for (int i = 0; i < messages.size(); i++) {
141	                Outgoing m = messages.get(i);
142	                if (m.sent()) {
143	                    messages.set(i, new Outgoing(m.channel(), testAddress, "[TESTE] " + m.subject(),
144	                            "Destinatário original: " + m.to() + "\n" + m.body(),
145	                            MessageStatus.SENT, m.guestAddress(), m.copy()));
146	                }
147	            }
148	        };
149	    }
150	
151	    static String key(String address) {
152	        return address == null ? "" : address.toLowerCase(Locale.ROOT);
153	    }
154	}
155	package br.com.marealta;
156	
157	import com.zaxxer.hikari.HikariConfig;
158	import com.zaxxer.hikari.HikariDataSource;
159	import java.sql.Connection;
160	import java.sql.SQLException;
161	import java.sql.Statement;
162	
163	/** Pool de conexões, criação do esquema e transações. */
164	public final class Database implements AutoCloseable {
165	    private final HikariDataSource ds;
166	
167	    public interface Work<T> {
168	        T run(Connection c) throws SQLException;
169	    }
170	
171	    public Database(String url, String user, String password) {
172	        HikariConfig hc = new HikariConfig();
173	        hc.setJdbcUrl(url);
174	        if (user != null) hc.setUsername(user);
175	        if (password != null) hc.setPassword(password);
176	        hc.setMaximumPoolSize(10);
177	        hc.setInitializationFailTimeout(-1);
178	        this.ds = new HikariDataSource(hc);
179	    }
180	
181	    /** Cria o que falta no banco; espera o banco ficar disponível se preciso. */
