276	import br.com.marealta.Domain.RatePlan;
277	import br.com.marealta.Domain.Room;
278	import java.math.BigDecimal;
279	import java.math.RoundingMode;
280	import java.time.LocalDate;
281	import java.time.Month;
282	
283	/** Cálculo de preço. Todo valor é arredondado a centavos (meio para o par) a cada passo. */
284	public final class Pricing {
285	    private Pricing() {}
286	
287	    private static final BigDecimal PEAK_FACTOR = new BigDecimal("1.20");
288	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
289	
290	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
291	
292	    /** Alta temporada: de 15/12 ao fim de fevereiro, e julho inteiro. */
293	    public static boolean isPeakSeason(LocalDate night) {
294	        Month m = night.getMonth();
295	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
296	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
297	    }
298	
299	    public static BigDecimal nightPrice(Room room, LocalDate night) {
300	        BigDecimal rate = room.nightlyRate();
301	        if (isPeakSeason(night)) {
302	            rate = rate.multiply(PEAK_FACTOR);
303	        }
304	        return money(rate);
305	    }
306	
307	    /** As noites são as datas de checkIn (inclusive) a checkOut (exclusive). */
308	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
309	        BigDecimal subtotal = BigDecimal.ZERO.setScale(2);
310	        int nights = 0;
311	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
312	            subtotal = subtotal.add(nightPrice(room, d));
313	            nights++;
314	        }
315	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
316	                ? money(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
317	                : money(BigDecimal.ZERO);
318	        return new Quote(nights, subtotal, discount, money(subtotal.subtract(discount)));
319	    }
320	
321	    public static BigDecimal money(BigDecimal v) {
322	        return v.setScale(2, RoundingMode.HALF_EVEN);
323	    }
324	}
