352	        sb.append("Entrada: ").append(BR_DATE.format(checkIn))
353	                .append(" | Saída: ").append(BR_DATE.format(checkOut))
354	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
355	        sb.append("Diárias: ").append(brl(subtotal)).append('\n');
356	        if (discount.signum() > 0) {
357	            sb.append("Desconto: ").append(brl(discount)).append('\n');
358	        }
359	        sb.append("Total: ").append(brl(total));
360	        return sb.toString();
361	    }
