363	    /** 1234.56 -> "R$ 1.234,56" (sem depender do locale da JVM). */
364	    public static String brl(BigDecimal v) {
365	        String plain = Pricing.money(v).abs().toPlainString();
366	        int dot = plain.indexOf('.');
367	        String ints = plain.substring(0, dot);
368	        StringBuilder grouped = new StringBuilder();
369	        for (int i = 0; i < ints.length(); i++) {
370	            if (i > 0 && (ints.length() - i) % 3 == 0) {
371	                grouped.append('.');
372	            }
373	            grouped.append(ints.charAt(i));
374	        }
375	        return (v.signum() < 0 ? "-R$ " : "R$ ") + grouped + "," + plain.substring(dot + 1);
376	    }
