     1	package br.com.marealta;
     2	
     3	import static org.junit.jupiter.api.Assertions.*;
     4	
     5	import br.com.marealta.Config.Notifications;
     6	import br.com.marealta.Config.Scope;
     7	import br.com.marealta.Domain.RatePlan;
     8	import br.com.marealta.Domain.Room;
     9	import br.com.marealta.Domain.RoomType;
    10	import br.com.marealta.Messaging.*;
    11	import java.math.BigDecimal;
    12	import java.time.LocalDate;
    13	import java.time.LocalTime;
    14	import java.time.ZoneId;
    15	import java.time.ZonedDateTime;
    16	import java.util.List;
    17	import org.junit.jupiter.api.Test;
    18	
    19	class DomainTest {
    20	    static final Room STANDARD = new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90"));
    21	    static final Room DELUXE = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));
    22	
    23	    @Test
    24	    void peakSeasonBoundaries() {
    25	        assertFalse(Pricing.isPeakSeason(LocalDate.of(2027, 12, 14)));
    26	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 12, 15)));
    27	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2028, 2, 29)));
    28	        assertFalse(Pricing.isPeakSeason(LocalDate.of(2028, 3, 1)));
    29	        assertTrue(Pricing.isPeakSeason(LocalDate.of(2027, 7, 31)));
    30	        assertFalse(Pricing.isPeakSeason(LocalDate.of(2027, 8, 1)));
    31	    }
    32	
    33	    @Test
    34	    void peakQuote() {
    35	        var q = Pricing.quote(STANDARD, LocalDate.of(2027, 7, 10), LocalDate.of(2027, 7, 12), RatePlan.STANDARD);
    36	        assertEquals(new BigDecimal("599.76"), q.subtotal());
    37	        assertEquals(new BigDecimal("0.00"), q.discount());
    38	        assertEquals(new BigDecimal("599.76"), q.total());
    39	        assertEquals(2, q.nights());
    40	    }
    41	
    42	    @Test
    43	    void nonRefundableDiscountUsesHalfEven() {
    44	        // 3 noites de 249.90 = 749.70; 15% = 112.455 -> 112.46 (meio para o par: ...5 com 5 antes -> 112.46)
    45	        var q = Pricing.quote(STANDARD, LocalDate.of(2027, 3, 1), LocalDate.of(2027, 3, 4), RatePlan.NON_REFUNDABLE);
    46	        assertEquals(new BigDecimal("749.70"), q.subtotal());
    47	        assertEquals(new BigDecimal("112.46"), q.discount());
    48	        assertEquals(new BigDecimal("637.24"), q.total());
    49	    }
    50	
    51	    @Test
    52	    void stayCrossingIntoPeakPricesEachNight() {
    53	        // 14/12 normal, 15/12 alta
    54	        var q = Pricing.quote(DELUXE, LocalDate.of(2027, 12, 14), LocalDate.of(2027, 12, 16), RatePlan.STANDARD);
    55	        assertEquals(new BigDecimal("389.90").add(new BigDecimal("467.88")), q.subtotal());
    56	    }
    57	
    58	    @Test
    59	    void receiptText() {
    60	        var r = new Receipt(7, "Carla Dias", "111.222.333-44", 201, RoomType.DELUXE,
    61	                LocalDate.of(2027, 3, 10), LocalDate.of(2027, 3, 12), 2,
    62	                new BigDecimal("779.80"), new BigDecimal("0.00"), new BigDecimal("779.80"));
    63	        assertEquals("""
    64	                Comprovante de reserva nº 7
    65	                Hóspede: Carla Dias (CPF 111.222.333-44)
    66	                Quarto: 201 (DELUXE)
    67	                Entrada: 10/03/2027 | Saída: 12/03/2027 | 2 diárias
    68	                Diárias: R$ 779,80
    69	                Total: R$ 779,80""", r.render());
    70	        assertEquals("R$ 1.234.567,05", Receipt.brl(new BigDecimal("1234567.05")));
    71	        var d = new Receipt(1, "A", "B", 101, RoomType.STANDARD, LocalDate.of(2027, 3, 10),
    72	                LocalDate.of(2027, 3, 11), 1, new BigDecimal("100.00"), new BigDecimal("15.00"), new BigDecimal("85.00"));
    73	        assertTrue(d.render().contains("| 1 diária\nDiárias: R$ 100,00\nDesconto: R$ 15,00\nTotal: R$ 85,00"));
    74	    }
    75	
    76	    @Test
    77	    void addressValidation() {
    78	        assertTrue(Messaging.isValidAddress("ana@gmail.com"));
    79	        assertTrue(Messaging.isValidAddress("a@b.c.d"));
    80	        for (String bad : new String[] {"ana@gmail", "ana.gmail.com", "@gmail.com", "a@@b.com", "a@b@c.com",
    81	                "ana@.com", "ana@gmail.", "ana@gm..com", "", "a b@c.com"}) {
    82	            assertFalse(Messaging.isValidAddress(bad), bad);
    83	        }
    84	    }
    85	
    86	    // ---------- cadeia de regras ----------
    87	
    88	    static final ZonedDateTime NOON = ZonedDateTime.of(2027, 3, 1, 12, 0, 0, 0, ZoneId.of("America/Sao_Paulo"));
    89	    static final Draft DRAFT = new Draft("ana@gmail.com", "Assunto", "Corpo");
    90	
    91	    static List<Outgoing> run(Notifications n, boolean test, Draft d, ZonedDateTime now, int sentToday) {
    92	        return new Pipeline(n, test).process(d, new Context(test, now, a -> sentToday));
    93	    }
    94	
    95	    @Test
    96	    void liveSendsWithArchiveCopy() {
    97	        var out = run(Notifications.defaults(), false, DRAFT, NOON, 0);
    98	        assertEquals(2, out.size());
    99	        assertEquals("ana@gmail.com", out.get(0).to());
   100	        assertEquals("arquivo@pousadamarealta.com.br", out.get(1).to());
   101	        assertEquals("[Cópia] Assunto", out.get(1).subject());
   102	        assertEquals("Corpo", out.get(1).body());
   103	    }
   104	
   105	    @Test
   106	    void invalidAddressIsBlockedWithoutCopy() {
   107	        for (boolean test : new boolean[] {false, true}) {
   108	            var out = run(Notifications.defaults(), test, new Draft("ana@gmail", "S", "B"), NOON, 0);
   109	            assertEquals(1, out.size());
   110	            assertEquals(MessageStatus.BLOCKED, out.get(0).status());
   111	            assertEquals("ana@gmail", out.get(0).to());
   112	            assertEquals("S", out.get(0).subject());
   113	        }
   114	    }
   115	
   116	    @Test
   117	    void testModeRedirectsEverything() {
   118	        var out = run(Notifications.defaults(), true, DRAFT, NOON, 0);
   119	        assertEquals(1, out.size());
   120	        assertEquals("testes@pousadamarealta.com.br", out.get(0).to());
   121	        assertEquals("[TESTE] Assunto", out.get(0).subject());
   122	        assertEquals("Destinatário original: ana@gmail.com\nCorpo", out.get(0).body());
   123	    }
   124	
   125	    @Test
   126	    void testModeNeverLeaksEvenWithArchiveCopyEnabled() {
   127	        var n = withScopes(Scope.ALWAYS, Scope.ALWAYS, Scope.NEVER, Scope.NEVER);
   128	        var out = run(n, true, DRAFT, NOON, 0);
   129	        assertEquals(2, out.size());
   130	        for (Outgoing m : out) assertEquals("testes@pousadamarealta.com.br", m.to());
   131	        assertEquals("[TESTE] [Cópia] Assunto", out.get(1).subject());
   132	        assertEquals("Destinatário original: arquivo@pousadamarealta.com.br\nCorpo", out.get(1).body());
   133	    }
   134	
   135	    @Test
   136	    void archiveCopyCanBeDisabled() {
   137	        var n = withScopes(Scope.ALWAYS, Scope.NEVER, Scope.NEVER, Scope.NEVER);
   138	        assertEquals(1, run(n, false, DRAFT, NOON, 0).size());
   139	    }
   140	
   141	    @Test
   142	    void quietHoursBlock() {
   143	        var n = withScopes(Scope.ALWAYS, Scope.LIVE_ONLY, Scope.ALWAYS, Scope.NEVER);
   144	        var night = NOON.withHour(2);
   145	        var out = run(n, false, DRAFT, night, 0);
   146	        assertEquals(1, out.size());
   147	        assertEquals(MessageStatus.BLOCKED, out.get(0).status());
   148	        assertEquals(MessageStatus.SENT, run(n, false, DRAFT, NOON, 0).get(0).status());
   149	        assertEquals(MessageStatus.SENT, run(n, false, DRAFT, NOON.withHour(7), 0).get(0).status());
   150	        assertEquals(MessageStatus.BLOCKED, run(n, false, DRAFT, NOON.withHour(22), 0).get(0).status());
   151	        // só em modo de teste: fora dele não bloqueia
   152	        var testOnly = withScopes(Scope.ALWAYS, Scope.LIVE_ONLY, Scope.TEST_ONLY, Scope.NEVER);
   153	        assertEquals(MessageStatus.SENT, run(testOnly, false, DRAFT, night, 0).get(0).status());
   154	        assertEquals(MessageStatus.BLOCKED, run(testOnly, true, DRAFT, night, 0).get(0).status());
   155	    }
   156	
   157	    @Test
   158	    void dailyLimitBlocks() {
   159	        var n = withScopes(Scope.ALWAYS, Scope.LIVE_ONLY, Scope.NEVER, Scope.LIVE_ONLY); // limite 2
   160	        assertEquals(MessageStatus.SENT, run(n, false, DRAFT, NOON, 1).get(0).status());
   161	        assertEquals(MessageStatus.BLOCKED, run(n, false, DRAFT, NOON, 2).get(0).status());
   162	        assertEquals(1, run(n, false, DRAFT, NOON, 2).size());
   163	        assertEquals(MessageStatus.SENT, run(n, true, DRAFT, NOON, 2).get(0).status());
   164	    }
   165	
   166	    static Notifications withScopes(Scope validation, Scope archive, Scope quiet, Scope limit) {
   167	        var d = Notifications.defaults();
   168	        return new Notifications(validation, archive, quiet, limit, d.archiveAddress(), d.testAddress(),
   169	                LocalTime.of(22, 0), LocalTime.of(7, 0), 2);
   170	    }
   171	}

